            rdf:object she:AntibioticResistanceGenes ] ;
    skos:narrower she:Antibiotics ;
    skos:prefLabel "pharmaceuticals" ;
    she:inputsFrom she:EffluentDischarge,
        she:GrazingLivestock,
        she:ManureSpreading,
        she:SewageSludgeSpreading ;
    she:isEmittedTo she:Soils .

she:Antibiotics a skos:Concept ;
