she:SewageSludge a skos:Concept ;
    skos:prefLabel "sewage sludge" .

she:AntibioticResistanceGenes a skos:Concept ;
    skos:prefLabel "antibiotic resistance genes" .

she:AntimicrobialResistance a skos:Concept ;
    skos:prefLabel "antimicrobial resistance" .

she:Cycon2019 a dcterms:BibliographicResource ;
