she:OrganicSoils a skos:Concept ;
    dcterms:source she:Drosler2014,
        she:FAO2006 ;
    sio:SIO_000202 [ agrontology:isCausedBy she:Climate,
                she:Vegetation ;
            rdf:object she:SoilOrganicMatter ] ;
    skos:prefLabel "organic soils" ;
    wdt:P1889 [ rdf:object she:MineralSoils ;
            she:isIndicatedBy she:SpecificCriteria ] .

she:Climate a skos:Concept ;
    skos:prefLabel "climate" .

she:CultivatedLand a skos:Concept ;
    skos:prefLabel "cultivated land" .

she:HighOrganicCarbonContent a skos:Concept ;
    dcterms:source she:Drosler2014,
        she:FAO2006 ;
    skos:prefLabel "high organic carbon content" .

she:MineralSoils a skos:Concept ;
    dcterms:source she:Drosler2014,
        she:FAO2006 ;
    sio:SIO_000202 [ sorelm:hasLowerBound 0 ;
            sorelm:hasUpperBound "20%"^^qudt:integerPercentage ;
            rdf:object she:SoilOrganicMatter ] ;
    skos:prefLabel "mineral soils" ;
    she:forms she:CultivatedLand .

she:SpecificCriteria a skos:Concept ;
    agrontology:includes she:HighOrganicCarbonContent,
        she:ThickOrganicHorizon,
        she:WaterSaturationEpisodePossibility ;
    dcterms:source she:Drosler2014,
        she:FAO2006 ;
    skos:prefLabel "specific criteria" .

she:ThickOrganicHorizon a skos:Concept ;
    dcterms:source she:Drosler2014,
        she:FAO2006 ;
    skos:prefLabel "thick organic horizon" .

she:Vegetation a skos:Concept ;
    skos:prefLabel "vegetation" .

she:WaterSaturationEpisodePossibility a skos:Concept ;
    dcterms:source she:Drosler2014,
        she:FAO2006 ;
    skos:prefLabel "water saturation episode possibility" .

she:SoilOrganicMatter a skos:Concept ;
    skos:prefLabel "soil organic matter" .

she:Drosler2014 a dcterms:BibliographicResource ;
    dcterms:date "2014" ;
    skos:prefLabel "IPCC guidelines for national GHG inventories" .

she:FAO2006 a dcterms:BibliographicResource ;
    dcterms:date "2006" ;
    skos:altLabel "FAO guidelines" ;
    skos:prefLabel "Food and Agriculture Organization guidelines" .

