she:AreaThreatenedByPipingErosion a skos:Concept ;
    agrontology:greaterThan [ dcterms:source she:Faulkner2006 ;
            qudt:numericValue "260000"^^xsd:int ;
            qudt:unit unit:KiloM2 ;
