she:EU a sorepsg:Region ;
    skos:prefLabel "EU" .

she:Europe a schema:Continent ;
    skos:prefLabel "Europe" .

she:Farmlands a skos:Concept ;
    skos:prefLabel "farmlands" .

she:Faulkner2006 a dcterms:BibliographicResource ;
    dcterms:date "2006" .

she:Grasslands a skos:Concept ;
    skos:prefLabel "grasslands" .

she:Gullies a skos:Concept ;
    skos:prefLabel "gullies" .

she:GullyErosion a skos:Concept ;
    skos:prefLabel "gully erosion" .

she:GullyFormation a skos:Concept ;
    skos:prefLabel "gully formation" .

she:GullyHeadcutRetreatingRates a skos:Concept ;
    skos:prefLabel "gully headcut retreating rates" .

she:Pipes a skos:Concept ;
    dcterms:source she:BernatekJakielPoesen2018 ;
    skos:broader she:UndergroundChannels ;
    skos:definition "Pipes are underground channels formed by piping erosion." ;
    skos:prefLabel "pipes" ;
    she:isConvertedTo [ sio:SIO_000635 she:PipeRoofCollapse ;
            rdf:object she:Gullies ] .

she:SoilLosses a skos:Concept ;
    af-x:AFX_0002696 [ agrontology:isCausedBy she:PipingErosion ;
            obo:BFO_0000066 she:Grasslands ;
            dcterms:source she:BernatekJakielPoesen2018,
                she:Verachtert2011 ;
            qudt:unit unit:TONNE-PER-HA-YR ;
            sorelm:hasInterval "1.3-15" ;
            prov:atLocation she:Europe ] ;
    sorelm:hasUpperBound [ agrontology:isCausedBy she:PipingErosion ;
            obo:BFO_0000066 she:Farmlands ;
            dcterms:source she:DiazSinoga2015 ;
            qudt:numericValue "120"^^xsd:int ;
            qudt:unit unit:TONNE-PER-HA-YR ;
            prov:atLocation she:Spain ] ;
    skos:prefLabel "soil losses" .

she:SoilParticles a skos:Concept ;
    skos:prefLabel "soil particles" .

she:Spain a schema:Country ;
    skos:prefLabel "Spain" .

she:UndergroundChannels a skos:Concept ;
    skos:prefLabel "underground channels" .

she:Verachtert2011 a dcterms:BibliographicResource ;
    dcterms:date "2011" .

she:PipeRoofCollapse a skos:Concept ;
    skos:prefLabel "pipe roof collapse" .

she:PipingErosion a skos:Concept ;
    agrontology:affects she:SoilParticles ;
    agrontology:causes she:SoilLosses ;
    agrontology:isCausedBy she:ConcentratedSubsurfaceFlows ;
    obo:RO_0002213 she:GullyErosion,
        she:GullyFormation,
        she:GullyHeadcutRetreatingRates ;
    dcterms:source she:BernatekJakielPoesen2018 ;
    skos:definition "Piping erosion is the removal of soil particles by concentrated subsurface flows, leading to the formation of underground channels called pipes." ;
    skos:prefLabel "piping erosion" ;
    she:forms she:Pipes ;
    she:isIndicatedBy she:PipeRoofCollapse .

she:BernatekJakielPoesen2018 a dcterms:BibliographicResource ;
    dcterms:date "2018" .

