she:AgriculturalSoils a skos:Concept ;
    sio:SIO_000202 [ agrontology:smallerThan [ qudt:numericValue "123"^^xsd:int ;
                    qudt:unit unit:MilliGM-PER-KiloGM ] ;
            af-x:AFX_0000408 she:BiomassProduction ;
            obo:BFO_0000066 she:EU,
                she:UnitedKingdom ;
            rdf:object she:ExchangeableKConcentrations,
                she:LowKLevels ;
            biolink:has_percentage "16%"^^qudt:integerPercentage ],
        [ agrontology:smallerThan [ qudt:numericValue "247"^^xsd:int ;
                    qudt:unit unit:MilliGM-PER-KiloGM ] ;
            af-x:AFX_0000408 she:BiomassProduction ;
            obo:BFO_0000066 she:EU,
                she:UnitedKingdom ;
            rdf:object she:ExchangeableKConcentrations,
                she:LowKLevels ;
