@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix obo: <http://purl.obolibrary.org/obo/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix she: <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:ClimateChange a skos:Concept ;
    agrontology:causes she:SoilDegradation ;
    dcterms:source she:BanerjeeVanDerHeijden2023 ;
    skos:prefLabel "climate change" .

she:Drought a skos:Concept ;
    agrontology:causes she:SoilMoistureDepletion ;
    obo:RO_0002213 she:Desertification,
        she:SoilErosion ;
    dcterms:source she:Ferreira2022 ;
    skos:prefLabel "drought" .

she:ExcessiveRainfall a skos:Concept ;
    agrontology:causes she:NutrientLeaching,
        she:SoilErosion,
        she:Waterlogging ;
    dcterms:source she:Ferreira2022 ;
    skos:prefLabel "excessive rainfall" .

she:ExtremeTemperatureFluctuations a skos:Concept ;
    agrontology:affects she:SoilStability,
        she:SoilStructure ;
    obo:RO_0002213 she:SoilCompaction,
        she:SoilErosion,
        she:SoilSalinisation ;
    dcterms:source she:Daliakopoulos2016,
        she:Kaushal2023,
        she:Kelishadi2018,
        she:Panagos2021 ;
    skos:prefLabel "extreme temperature fluctuations" .

she:PrecipitationPatterns a skos:Concept ;
    agrontology:affects she:Soil ;
    agrontology:includes she:RainfallDistribution,
        she:RainfallFrequency,
        she:RainfallIntensity ;
    dcterms:source she:Meng2021 ;
    skos:prefLabel "precipitation patterns" .

she:ProlongedDroughtPeriods a skos:Concept ;
    agrontology:affects she:SoilResources ;
    skos:prefLabel "prolonged drought periods" .

she:RisingTemperatures a skos:Concept ;
    agrontology:affects [ agrontology:isCausedBy [ she:alters she:HeterotrophicActivity,
                        she:NutrientCyclingProcesses,
                        she:OrganicMatterDecompositionRates ] ;
            rdf:object she:SoilCondition ],
        she:SoilResources ;
    skos:prefLabel "rising temperatures" .

she:WarmerTemperatures a skos:Concept ;
    obo:RO_0002213 she:SoilOrganicMatterDecomposition ;
    dcterms:source she:Wang2021 ;
    skos:prefLabel "warmer temperatures" .

she:CarbonLoss a skos:Concept ;
    dcterms:source she:Wang2021 ;
    skos:prefLabel "carbon loss" .

she:Desertification a skos:Concept ;
    dcterms:source she:Ferreira2022 ;
    skos:prefLabel "desertification" .

she:HeterotrophicActivity a skos:Concept ;
    skos:prefLabel "heterotrophic activity" .

she:NutrientCyclingProcesses a skos:Concept ;
    skos:prefLabel "nutrient cycling processes" .

she:NutrientLeaching a skos:Concept ;
    dcterms:source she:Ferreira2022 ;
    skos:prefLabel "nutrient leaching" .

she:Nutrients a skos:Concept ;
    skos:prefLabel "nutrients" .

she:OrganicMatterDecompositionRates a skos:Concept ;
    skos:prefLabel "organic matter decomposition rates" .

she:RainfallDistribution a skos:Concept ;
    dcterms:source she:Meng2021 ;
    skos:prefLabel "rainfall distribution" .

she:RainfallFrequency a skos:Concept ;
    dcterms:source she:Meng2021 ;
    skos:prefLabel "rainfall frequency" .

she:RainfallIntensity a skos:Concept ;
    dcterms:source she:Meng2021 ;
    skos:prefLabel "rainfall intensity" .

she:Soil a skos:Concept ;
    dcterms:source she:Meng2021 ;
    skos:prefLabel "soil" .

she:SoilCompaction a skos:Concept ;
    dcterms:source she:Daliakopoulos2016,
        she:Kaushal2023,
        she:Kelishadi2018,
        she:Panagos2021 ;
    skos:prefLabel "soil compaction" .

she:SoilCondition a skos:Concept ;
    skos:prefLabel "soil condition" .

she:SoilDegradation a skos:Concept ;
    dcterms:source she:BanerjeeVanDerHeijden2023 ;
    skos:prefLabel "soil degradation" .

she:SoilFertility a skos:Concept ;
    dcterms:source she:Wang2021 ;
    skos:prefLabel "soil fertility" .

she:SoilMoistureDepletion a skos:Concept ;
    dcterms:source she:Ferreira2022 ;
    skos:prefLabel "soil moisture depletion" .

she:SoilOrganicMatterDecomposition a skos:Concept ;
    agrontology:causes she:CarbonLoss ;
    obo:RO_0002212 she:SoilFertility ;
    dcterms:source she:Wang2021 ;
    skos:prefLabel "soil organic matter decomposition" .

she:SoilSalinisation a skos:Concept ;
    dcterms:source she:Daliakopoulos2016,
        she:Kaushal2023,
        she:Kelishadi2018,
        she:Panagos2021 ;
    skos:prefLabel "soil salinisation" .

she:SoilStability a skos:Concept ;
    dcterms:source she:Daliakopoulos2016,
        she:Kaushal2023,
        she:Kelishadi2018,
        she:Panagos2021 ;
    skos:prefLabel "soil stability" .

she:SoilStructure a skos:Concept ;
    dcterms:source she:Daliakopoulos2016,
        she:Kaushal2023,
        she:Kelishadi2018,
        she:Panagos2021 ;
    skos:prefLabel "soil structure" .

she:Water a skos:Concept ;
    skos:prefLabel "water" .

she:Waterlogging a skos:Concept ;
    dcterms:source she:Ferreira2022 ;
    skos:prefLabel "waterlogging" .

she:BanerjeeVanDerHeijden2023 a dcterms:BibliographicResource ;
    dcterms:date "2023" .

she:SoilResources a skos:Concept ;
    skos:narrower she:Nutrients,
        she:Water ;
    skos:prefLabel "soil resources" .

she:SoilErosion a skos:Concept ;
    dcterms:source she:Daliakopoulos2016,
        she:Ferreira2022,
        she:Kaushal2023,
        she:Kelishadi2018,
        she:Panagos2021 ;
    skos:prefLabel "soil erosion" .

she:Wang2021 a dcterms:BibliographicResource ;
    dcterms:date "2021" .

she:Meng2021 a dcterms:BibliographicResource ;
    dcterms:date "2021" .

she:Daliakopoulos2016 a dcterms:BibliographicResource ;
    dcterms:date "2016" .

she:Kaushal2023 a dcterms:BibliographicResource ;
    dcterms:date "2023" .

she:Kelishadi2018 a dcterms:BibliographicResource ;
    dcterms:date "2018" .

she:Panagos2021 a dcterms:BibliographicResource ;
    dcterms:date "2021" .

she:Ferreira2022 a dcterms:BibliographicResource ;
    dcterms:date "2022" .

@prefix agrontology: <http://aims.fao.org/aos/agrontology#> .
@prefix bao: <http://www.bioassayontology.org/bao#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix obo: <http://purl.obolibrary.org/obo/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix she: <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:CalcareousSoil a skos:Concept ;
    obo:RO_0000053 she:AlkalineSoilpH,
        she:HighNaturalBufferCapacity,
        she:StableSoilpH ;
    skos:prefLabel "calcareous soil" .

she:CarbonateDepletion a skos:Concept ;
    obo:RO_0002502 she:CarbonateDissolutionRate ;
    obo:RO_0002552 she:AlkalineSoilpH,
        she:StableSoilpH ;
    skos:prefLabel "carbonate depletion" .

she:SoilAcidNeutralisationCapacity a skos:Concept ;
    dcterms:source she:DeVriesBreeuwsma1987,
        she:Guo2010 ;
    skos:prefLabel "soil acid neutralisation capacity" ;
    skos:related she:SoilAcidification .

she:SoilFunctions a skos:Concept ;
    dcterms:source she:Siciliano2014 ;
    skos:narrower she:OrganismHabitat ;
    skos:prefLabel "soil functions" .

she:ToxicElements a skos:Concept ;
    skos:narrower she:Aluminium,
        she:Cadmium,
        she:HeavyMetals ;
    skos:prefLabel "toxic elements" .

she:Aluminium a skos:Concept ;
    skos:prefLabel "aluminium" .

she:BaseSaturation a skos:Concept ;
    skos:prefLabel "base saturation" .

she:Biodiversity a skos:Concept ;
    dcterms:source she:Siciliano2014 ;
    skos:prefLabel "biodiversity" .

she:Cadmium a skos:Concept ;
    skos:prefLabel "cadmium" .

she:CarbonateDissolutionRate a skos:Concept ;
    skos:prefLabel "carbonate dissolution rate" .

she:HeavyMetals a skos:Concept ;
    skos:prefLabel "heavy metals" .

she:LowBufferCapacity a skos:Concept ;
    skos:prefLabel "low buffer capacity" .

she:LowOrganicMatterContent a skos:Concept ;
    skos:prefLabel "low organic matter content" .

she:NoncalcareousSoil a skos:Concept ;
    obo:RO_0000053 she:LowBufferCapacity ;
    skos:narrower she:SandySoil ;
    skos:prefLabel "non-calcareous soil" .

she:NutrientAvailability a skos:Concept ;
    skos:prefLabel "nutrient availability" .

she:NutrientMobility a skos:Concept ;
    skos:prefLabel "nutrient mobility" .

she:PrimaryProductivity a skos:Concept ;
    dcterms:source she:Bolan2003,
        she:HarteminkBarrow2023,
        she:PaganiMallarino2012 ;
    skos:prefLabel "primary productivity" .

she:SoilAcidification a skos:Concept ;
    obo:RO_0002212 [ obo:BFO_0000066 she:NoncalcareousSoil,
                she:SandySoil ;
            rdf:object she:BaseSaturation,
                she:SoilpH ] ;
    dcterms:source she:DeVriesBreeuwsma1987,
        she:Guo2010 ;
    skos:definition "Soil acidification is defined as a decrease in the acid neutralisation capacity of the soil." ;
    skos:prefLabel "soil acidification" .

she:SoilHealth a skos:Concept ;
    skos:prefLabel "soil health" .

she:SoilpH a skos:Concept ;
    agrontology:affects she:NutrientAvailability,
        she:NutrientMobility,
        she:OrganismHabitat,
        she:PrimaryProductivity,
        she:SurroundingWaterBodyQuality,
        she:ToxicElementAvailability,
        she:ToxicElementMobility ;
    dcterms:source she:Bolan2003,
        she:Dijkstra2004,
        she:HarteminkBarrow2023,
        she:HaynesSwift1986,
        she:PaganiMallarino2012,
        she:Siciliano2014 ;
    bao:BAO_0002586 she:SoilHealth ;
    skos:prefLabel "soil pH" .

she:SurroundingWaterBodyQuality a skos:Concept ;
    dcterms:source she:Dijkstra2004,
        she:HaynesSwift1986 ;
    skos:prefLabel "surrounding water body quality" .

she:ToxicElementAvailability a skos:Concept ;
    skos:prefLabel "toxic element availability" .

she:ToxicElementMobility a skos:Concept ;
    skos:prefLabel "toxic element mobility" .

she:AlkalineSoilpH a skos:Concept ;
    agrontology:isAchievedByMeansOf she:Carbonates,
        she:HighNaturalBufferCapacity ;
    skos:prefLabel "alkaline soil pH" .

she:Bolan2003 a dcterms:BibliographicResource ;
    dcterms:date "2003" .

she:Carbonates a skos:Concept ;
    skos:prefLabel "carbonates" .

she:DeVriesBreeuwsma1987 a dcterms:BibliographicResource ;
    dcterms:date "1987" .

she:Dijkstra2004 a dcterms:BibliographicResource ;
    dcterms:date "2004" .

she:Guo2010 a dcterms:BibliographicResource ;
    dcterms:date "2010" .

she:HarteminkBarrow2023 a dcterms:BibliographicResource ;
    dcterms:date "2023" .

she:HaynesSwift1986 a dcterms:BibliographicResource ;
    dcterms:date "1986" .

she:OrganismHabitat a skos:Concept ;
    agrontology:affects she:Biodiversity ;
    dcterms:source she:Siciliano2014 ;
    skos:prefLabel "organism habitat" .

she:PaganiMallarino2012 a dcterms:BibliographicResource ;
    dcterms:date "2012" .

she:SandySoil a skos:Concept ;
    obo:RO_0000053 she:LowOrganicMatterContent ;
    skos:prefLabel "sandy soil" .

she:StableSoilpH a skos:Concept ;
    agrontology:isAchievedByMeansOf she:Carbonates,
        she:HighNaturalBufferCapacity ;
    skos:prefLabel "stable soil pH" .

she:HighNaturalBufferCapacity a skos:Concept ;
    skos:prefLabel "high natural buffer capacity" .

she:Siciliano2014 a dcterms:BibliographicResource ;
    dcterms:date "2014" .

